source("setup.R")
pl <- function(x) try_(zulake:::parse_blob_list(charToRaw(enc2utf8(x)), "p/"))
D <- "Thu, 26 Nov 2026 16:04:00 GMT"
blob <- function(name, len = "5", date = D, extra = "", nameattr = "") sprintf("<Blob><Name%s>%s</Name><Properties><Last-Modified>%s</Last-Modified><Content-Length>%s</Content-Length></Properties>%s</Blob>", nameattr, name, date, len, extra)
doc <- function(items, marker = "<NextMarker />", pre = "") paste0('<?xml version="1.0" encoding="utf-8"?><EnumerationResults ServiceEndpoint="x">', pre, "<Blobs>", paste(items, collapse = ""), "</Blobs>", marker, "</EnumerationResults>")
t <- function(label, x) { r <- pl(x); cat("--", label, ": "); if (inherits(r, "condition")) cat("<", class(r)[1], ">", conditionMessage(r), "\n") else cat("names=", paste(encodeString(r$blobs$name, quote = '"'), collapse = ","), " size=", paste(r$blobs$size, collapse = ","), " mtime=", paste(r$blobs$modification_time, collapse=","), " marker=", encodeString(r$next_marker), "\n") }
t("plain", doc(blob("p/a")))
t("entity", doc(blob("p/a&amp;b&lt;c&#38;&#x41;&apos;&quot;")))
t("double-escaped", doc(blob("p/a&amp;amp;b")))
t("CDATA", doc(blob("<![CDATA[p/a<b]]>")))
t("CDATA with </Blob>", doc(blob("<![CDATA[p/a</Blob>b]]>")))
t("encoded attr", doc(blob("p/a%20b%EF%BF%BE", nameattr = ' Encoded="true"')))
t("encoded false", doc(blob("p/a%20b", nameattr = ' Encoded="false"')))
t("encoded bad", doc(blob("p/a%zz", nameattr = ' Encoded="true"')))
t("encoded NUL", doc(blob("p/a%00", nameattr = ' Encoded="true"')))
t("name ..", doc(blob("p/../x")))
t("leading slash", doc(blob("/p/a")))
t("hdi folder", doc(blob("p/dir", extra = "<Metadata><hdi_isfolder>true</hdi_isfolder></Metadata>")))
t("hdi folder TRUE", doc(blob("p/dir", extra = "<Metadata><hdi_isfolder>TRUE</hdi_isfolder></Metadata>")))
t("Hdi_isfolder key case", doc(blob("p/dir", extra = "<Metadata><Hdi_isfolder>true</Hdi_isfolder></Metadata>")))
t("hdi folder w/ space", doc(blob("p/dir", extra = "<Metadata><hdi_isfolder> true </hdi_isfolder></Metadata>")))
t("ResourceType directory", doc(sprintf("<Blob><Name>p/dir</Name><Properties><Last-Modified>%s</Last-Modified><Content-Length>0</Content-Length><ResourceType>directory</ResourceType></Properties></Blob>", D)))
t("metadata named Name before Name? (Metadata first)", doc(sprintf("<Blob><Metadata><Name>evil</Name></Metadata><Name>p/real</Name><Properties><Last-Modified>%s</Last-Modified><Content-Length>1</Content-Length></Properties></Blob>", D)))
t("metadata Content-Length key", doc(blob("p/a", extra = "<Metadata><Content-Length>99</Content-Length></Metadata>")))
t("metadata with key NextMarker", doc(blob("p/a", extra = "<Metadata><NextMarker>evil</NextMarker></Metadata>")))
t("Tags/OrMetadata w/ Properties", doc(sprintf("<Blob><Name>p/a</Name><OrMetadata><Properties>x</Properties></OrMetadata><Properties><Last-Modified>%s</Last-Modified><Content-Length>1</Content-Length></Properties></Blob>", D)))
t("size huge", doc(blob("p/a", "9007199254740992")))
t("size max", doc(blob("p/a", "9007199254740991")))
t("size neg", doc(blob("p/a", "-1")))
t("size empty", doc(blob("p/a", "")))
t("size 1e3", doc(blob("p/a", "1e3")))
t("size leading zeros", doc(blob("p/a", "00012")))
t("size ws", doc(blob("p/a", " 12")))
t("date bad", doc(blob("p/a", date = "2026-11-26T16:04:00Z")))
t("date Feb 30", doc(blob("p/a", date = "Mon, 30 Feb 2026 16:04:00 GMT")))
t("date sec 60", doc(blob("p/a", date = "Thu, 26 Nov 2026 23:59:60 GMT")))
t("date year 0000", doc(blob("p/a", date = "Thu, 26 Nov 0000 23:59:59 GMT")))
t("date wrong weekday", doc(blob("p/a", date = "Mon, 26 Nov 2026 16:04:00 GMT")))
t("marker", doc(blob("p/a"), "<NextMarker>abc&amp;d==</NextMarker>"))
t("marker ws", doc(blob("p/a"), "<NextMarker> </NextMarker>"))
t("marker in prefix elem", doc(blob("p/a"), "<NextMarker />", pre = "<Prefix>&lt;NextMarker&gt;x&lt;/NextMarker&gt;</Prefix>"))
t("Marker echo then NextMarker", doc(blob("p/a"), "<NextMarker>n2</NextMarker>", pre = "<Marker>n1</Marker>"))
t("no Blobs", '<EnumerationResults><NextMarker>m</NextMarker></EnumerationResults>')
t("empty Blobs self-closed, marker", '<EnumerationResults><Blobs /><NextMarker>m</NextMarker></EnumerationResults>')
t("two Blobs elements", paste0("<EnumerationResults><Blobs>", blob("p/a"), "</Blobs><Blobs>", blob("p/b"), "</Blobs><NextMarker /></EnumerationResults>"))
t("Blob with attr", doc('<Blob x="1"><Name>p/a</Name><Properties><Last-Modified>Thu, 26 Nov 2026 16:04:00 GMT</Last-Modified><Content-Length>1</Content-Length></Properties></Blob>'))
t("whitespace-pretty", doc(paste0("\n <Blob>\n  <Name>p/a</Name>\n  <Properties>\n <Last-Modified>", D, "</Last-Modified>\n <Content-Length>3</Content-Length>\n </Properties>\n </Blob>\n")))
t("name with newline/ws around", doc(blob("\n p/a \n")))
t("BOM", paste0("﻿", doc(blob("p/a"))))
t("error doc", '<?xml version="1.0"?><Error><Code>x</Code></Error>')
t("comment containing blob", doc(c("<!-- <Blob><Name>p/ghost</Name><Properties><Last-Modified>Thu, 26 Nov 2026 16:04:00 GMT</Last-Modified><Content-Length>1</Content-Length></Properties></Blob> -->", blob("p/a"))))
t("snapshot/version/deleted", doc(c(sprintf("<Blob><Name>p/a</Name><Snapshot>2020</Snapshot><Properties><Last-Modified>%s</Last-Modified><Content-Length>1</Content-Length></Properties></Blob>", D), sprintf("<Blob><Name>p/a</Name><Deleted>true</Deleted><Properties><Last-Modified>%s</Last-Modified><Content-Length>7</Content-Length></Properties></Blob>", D))))
t("numeric ref 0 / surrogate / big", doc(blob("p/a&#0;b&#xD800;c&#x110000;d&#99999999999999999999;")))
t("&#x with big hex", doc(blob("p/a&#xFFFFFFFFFF;")))
